ProcedurePrims.defineCommand("setup", 4378, 5682, (function() {
  world.ticker.clear();
  world.turtleManager.clearTurtles();
  world.clearPatches();
  world.clearDrawing();
  plotManager.clearAllPlots();
  OutputPrims.clear();
  if (world.observer.getGlobal("fixed-seed?")) {
    PrimChecks.math.randomSeed(4553, 4564, PrimChecks.validator.checkArg('RANDOM-SEED', 4553, 4564, 1, world.observer.getGlobal("seed")));
  }
  world.observer.setGlobal("run-finished?", false);
  world.observer.setGlobal("generated-total", 0);
  world.observer.setGlobal("completed-total", 0);
  world.observer.setGlobal("demand-seed", (Prims.ifElseValueBooleanCheck(world.observer.getGlobal("fixed-seed?")) ? world.observer.getGlobal("seed") : RandomPrims.randomLong(1000000)));
  if (PrimChecks.math.not(NLType.checks.isString(world.observer.getGlobal("selected-street")))) {
    world.observer.setGlobal("selected-street", "Collins St");
  }
  var R = ProcedurePrims.callCommand("setup-constants"); if (R === DeathInterrupt) { return R; }
  var R = ProcedurePrims.callCommand("load-real-traffic"); if (R === DeathInterrupt) { return R; }
  world.observer.setGlobal("gates", new TurtleSet([], world));
  world.observer.setGlobal("carparks", new TurtleSet([], world));
  world.observer.setGlobal("signals", new TurtleSet([], world));
  world.ticker.reset();
  if (Prims.equality(world.observer.getGlobal("baseline"), 0)) {
    world.observer.setGlobal("baseline", Extensions["TABLE"].prims["MAKE"]());
  }
  world.observer.setGlobal("trips-done", 0);
  world.observer.setGlobal("trip-time-sum", 0);
  world.observer.setGlobal("delay-sum", 0);
  world.observer.setGlobal("veh-seconds", 0);
  world.observer.setGlobal("stranded-count", 0);
  world.observer.setGlobal("recent-delays", []);
  world.observer.setGlobal("mouse-was-down?", false);
  world.observer.setGlobal("closure-applied?", false);
  world.observer.setGlobal("closure-desc", "none");
  world.resize(-120, 120, -102, 102);
  var R = ProcedurePrims.ask(world.patches(), function() { PrimChecks.patch.setVariable(5206, 5212, "pcolor", [22, 29, 39]); }, true); if (R !== undefined) { PrimChecks.procedure.preReturnCheck(5189, 5192, R); return R; }
  var R = ProcedurePrims.callCommand("build-osm-network"); if (R === DeathInterrupt) { return R; }
  var R = ProcedurePrims.callCommand("setup-count-sites"); if (R === DeathInterrupt) { return R; }
  world.ticker.reset();
  var R = ProcedurePrims.callCommand("setup-signals"); if (R === DeathInterrupt) { return R; }
  var R = ProcedurePrims.callCommand("setup-routing"); if (R === DeathInterrupt) { return R; }
  var R = ProcedurePrims.ask(world.linkManager.linksOfBreed("ROADS"), function() {
    PrimChecks.link.setVariable(5329, 5339, "base-count", (Prims.ifElseValueBooleanCheck(Extensions["TABLE"].prims["HAS-KEY?"](world.observer.getGlobal("baseline"), PrimChecks.procedure.callReporter(5377, 5385, "link-key"))) ? Extensions["TABLE"].prims["GET"](world.observer.getGlobal("baseline"), PrimChecks.procedure.callReporter(5407, 5415, "link-key")) : 0));
  }, true); if (R !== undefined) { PrimChecks.procedure.preReturnCheck(5313, 5316, R); return R; }
  if ((PrimChecks.validator.checkArg('AND', 5450, 5453, 2, world.observer.getGlobal("scheduled-closure?")) && Prims.equality(world.observer.getGlobal("closure-start-min"), 0))) {
    var R = ProcedurePrims.callCommand("apply-scenario-closure"); if (R === DeathInterrupt) { return R; }
  }
  var R = ProcedurePrims.callCommand("update-link-colors"); if (R === DeathInterrupt) { return R; }
  OutputPrims.print(StringPrims.word("Melbourne CBD traffic ready: ", world.observer.getGlobal("day-type"), " from ", world.observer.getGlobal("start-time"), ", shaped by SCATS counts."));
  OutputPrims.print(StringPrims.word("Closure: ", world.observer.getGlobal("closure-desc")));
}))
ProcedurePrims.defineCommand("setup-constants", 5690, 5932, (function() {
  world.observer.setGlobal("m-per-patch", 10);
  world.observer.setGlobal("block-w", 201.2);
  world.observer.setGlobal("row-h", 100.6);
  world.observer.setGlobal("veh-len", 7);
  world.observer.setGlobal("accel", 1.5);
  world.observer.setGlobal("decel", 3.5);
  world.observer.setGlobal("intergreen", 6);
  world.observer.setGlobal("big", 1000000000);
  world.observer.setGlobal("little-st-kmh", 20);
  world.observer.setGlobal("give-way-delay", 6);
  world.observer.setGlobal("vmax", PrimChecks.math.div(5926, 5927, PrimChecks.validator.checkArg('/', 5926, 5927, 1, world.observer.getGlobal("speed-limit-kmh")), 3.6));
}))
